// [MEDIUM_PRIORITY] VALIDATION: Long conversion safe
// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.voice.wakewordimport timber.log.Timberimport android.content.Contextimport com.roshan.persona.voice.capture.AudioCapturePipelineimport com.roshan.persona.voice.capture.AudioSourceimport com.roshan.persona.voice.capture.CircularAudioBufferimport com.roshan.persona.voice.capture.VoiceActivityDetectorimport kotlinx.coroutines.CoroutineDispatcherimport kotlinx.coroutines.CoroutineScopeimport kotlinx.coroutines.Jobimport kotlinx.coroutines.flow.MutableSharedFlowimport kotlinx.coroutines.flow.asSharedFlowimport kotlinx.coroutines.isActiveimport kotlinx.coroutines.launchimport kotlinx.coroutines.yieldimport java.io.Fileimport java.util.concurrent.atomic.AtomicBoolean/** * NOUS — Software Wake Word Detector (Tier 2 fallback + confirmer). * * Two responsibilities: * *  1. **Always-on software fallback** — when the device has no SoundTrigger *     DSP (cheap phones, Android < 8, or DSP not exposed by OEM), this class *     runs OpenWakeWord in a tight loop on the CPU. Battery ~3 %/hour thanks *     to the VAD pre-filter (saves ~60 % per §4 "Battery Optimization"). * *  2. **Tier 2 confirmer** — when the hardware DSP fires a trigger, the *     [HardwareWakeWordDetector] calls [confirm] on this class to run *     software verification (OpenWakeWord + MFCC + speaker pre-check). *     This 2-stage confirmation reduces false positives by ~10×. * * ## OpenWakeWord pipeline (§4 OpenWakeWord Integration) * * ``` * audio chunk (20 ms) *      ↓ * 1. VAD pre-filter — skip non-voice chunks (saves battery) *      ↓ (voice detected) * 2. OpenWakeWord TFLite inference (4 MB model) *      ↓ (score > 0.7 threshold) * 3. MFCC 2nd-stage confirmation *      ↓ (MFCC matches enrolled template) * 4. Speaker pre-check (optional — owner voice only) *      ↓ (speaker matches) * FIRE onWakeWordDetected * ``` * * ## Testability * * The wake-word loop reads from an [AudioSource] (the same interface used by * [AudioCapturePipeline]). In production, both share the same * [AndroidAudioSource] — when the wake-word detector is in always-on mode, * the pipeline is *not* running, and vice versa. * * [WakeWordSoftwareConfirmer] is a separate singleton-style object so the * hardware detector can use it without instantiating a full * [SoftwareWakeWordDetector]. * * @param audioSource the mic input (shared with AudioCapturePipeline). * @param captureDispatcher single-threaded dispatcher for the mic loop. */class SoftwareWakeWordDetector(    private val context: Context,    private val config: WakeWordDetector.Config,    private val circularBuffer: CircularAudioBuffer,    private val onWakeWordDetected: (WakeWordDetector.WakeWordEvent) -> Unit,    private val audioSource: AudioSource,    private val vad: VoiceActivityDetector =        VoiceActivityDetector.EnergyBased(aggressiveness = config.vadAggressiveness),    private val captureDispatcher: CoroutineDispatcher,    private val confirmer: WakeWordSoftwareConfirmer = WakeWordSoftwareConfirmer.Impl,) : WakeWordDetector {    override val isHardwareAccelerated: Boolean = false    private val running = AtomicBoolean(false)    private var loopJob: Job? = null    override val isRunning: Boolean get() = running.get()    private val wakeWordModel: WakeWordTfliteModel? by lazy { loadModel() }    override fun start() {        if (!running.compareAndSet(false, true)) {            Timber.tag(TAG).w("start() called while already running — ignoring.")            return        }        if (wakeWordModel == null) {            Timber.tag(TAG).e("OpenWakeWord model not loaded — cannot start software detection.")            running.set(false)            return        }        Timber.tag(TAG).i("Starting software wake-word detection (OpenWakeWord, ~3 %/hour).")        loopJob = CoroutineScope(captureDispatcher).launch {            audioSource.start()            try {                while (isActive && running.get()) {                    val chunk = audioSource.readChunk()                    circularBuffer.write(chunk)                    // Stage 1: VAD pre-filter (60 % battery savings).                    if (!vad.hasVoice(chunk)) {                        yield()                        continue                    }                    // Stage 2: OpenWakeWord TFLite inference.                    val score = wakeWordModel?.infer(chunk) ?: 0f                    if (score < config.wakeWordThreshold) {                        yield()                        continue                    }                    // Stage 3 + 4: MFCC + speaker pre-check.                    val leadIn = circularBuffer.snapshot()                    val event = confirmer.confirm(leadIn, config)                    if (event != null) {                        Timber.tag(TAG).i("Software wake word confirmed (score=$score).")                        onWakeWordDetected(event)                        // After firing, pause briefly so we don't re-trigger                        // on the same audio.                        kotlinx.coroutines.delay(COOLDOWN_MS)                    }                    yield()                }            } catch (t: Throwable) {                Timber.tag(TAG).e("Software wake-word loop crashed", t)            } finally {                runCatching { audioSource.stop() }                running.set(false)                Timber.tag(TAG).i("Software wake-word detection stopped.")            }        }    }    override fun stop() {        if (!running.compareAndSet(true, false)) return        loopJob?.cancel()        loopJob = null    }    override fun release() {        stop()        runCatching { wakeWordModel?.close() }        runCatching { audioSource.release() }    }    // ──────────────────────────────────────────────────────────────────────    private fun loadModel(): WakeWordTfliteModel? {        val path = config.softwareModelPath        val file = File(path)        if (!file.exists()) {            Timber.tag(TAG).w("OpenWakeWord model not found at $path — software detection disabled.")            return null        }        return runCatching { WakeWordTfliteModel.load(file) }            .onFailure { Timber.tag(TAG).e("Failed to load OpenWakeWord model", it) }            .getOrNull()    }    companion object {        private const val TAG = "SwWakeWord"        /** Cooldown after a detection to prevent immediate re-trigger. */        private const val COOLDOWN_MS = 1_500L    }}// ──────────────────────────────────────────────────────────────────────────// WakeWordSoftwareConfirmer — shared between Hardware (Tier 2) and Software.// ──────────────────────────────────────────────────────────────────────────/** * Tier 2 confirmation logic — used by both [HardwareWakeWordDetector] (after * a DSP trigger) and [SoftwareWakeWordDetector] (after OpenWakeWord crosses * threshold). * * Runs (optionally): *  1. MFCC 2nd-stage confirmation — compare MFCC features of the trigger *     audio against an enrolled template. Reduces false positives 10×. *  2. Speaker pre-check — if owner voice print is enrolled, require match. * * Returns a [WakeWordDetector.WakeWordEvent] on confirmation, or null if * either stage rejects. */fun interface WakeWordSoftwareConfirmer {    /**     * @param audio  trigger audio (may be null if DSP fired without capture).     * @param config wake-word config (controls which stages run).     * @return confirmed event, or null to reject.     */    fun confirm(        audio: ShortArray?,        config: WakeWordDetector.Config,    ): WakeWordDetector.WakeWordEvent?    companion object {        /**         * Production confirmer. MFCC + speaker pre-check are backed by         * :native:openwakeword (TFLite) and :feature:voice.speaker (ECAPA-TDNN)         * — until those ship (Year 2 per §24), this implementation accepts         * any audio with reasonable energy as a confirmation. This is         * deliberate: hardware DSP false-positive rate is already ~3 %, and         * the false-positive cost is "NOUS opens STT and listens for 2 s"         * which is cheap and self-correcting.         */        val Impl = WakeWordSoftwareConfirmer { audio, config ->            if (audio == null || audio.isEmpty()) {                // No audio to confirm — accept hardware triggers that don't                // carry audio (rare; happens on some Qualcomm DSPs in deep                // sleep). Confidence is the hardware threshold.                return@WakeWordSoftwareConfirmer WakeWordDetector.WakeWordEvent(                    confidence = config.wakeWordThreshold,                    speakerMatch = !config.speakerPreCheck,                    audioTrigger = null,                )            }            // Stage 3: MFCC confirmation (if enabled).            if (config.mfccConfirmEnabled) {                val mfccScore = MfccTemplateMatcher.score(audio)                if (mfccScore < MFCC_CONFIRM_THRESHOLD) {                    Timber.tag("WakeWordConfirmer").d("MFCC confirmation failed (score=$mfccScore).")                    return@WakeWordSoftwareConfirmer null                }            }            // Stage 4: Speaker pre-check (if enabled).            val speakerMatch = if (config.speakerPreCheck) {                SpeakerPreCheck.matchesOwner(audio)            } else {                true            }            WakeWordDetector.WakeWordEvent(                confidence = 1.0f,  // confirmation stage accepts at full confidence                speakerMatch = speakerMatch,                audioTrigger = audio,            )        }        private const val MFCC_CONFIRM_THRESHOLD = 0.65f    }}// ──────────────────────────────────────────────────────────────────────────// MFCC + Speaker pre-check stubs.// Real implementations ship in :native:openwakeword (Step 5.7 ECAPA-TDNN).// ──────────────────────────────────────────────────────────────────────────/** MFCC feature extraction + template matching (TFLite). Stubbed until :native:openwakeword ships. */object MfccTemplateMatcher {    /** Returns similarity score 0.0–1.0 against enrolled wake-word template. */    fun score(audio: ShortArray): Float {        // Real impl: extract 13-coefficient MFCC over 25 ms frames, compare        // DTW distance against enrolled template. Until :native:openwakeword        // ships, return a permissive score based on signal energy (so we        // never reject a real wake word during early development).        var sumSq = 0L        for (s in audio) sumSq += s.toInt().toLong() * s.toInt().toLong()        val rms = kotlin.math.sqrt(sumSq.toDouble() / audio.size).toFloat()        // 0.5 baseline + 0.5 scaled by RMS, capped at 1.0.        return (0.5f + 0.5f * (rms / 4000f)).coerceAtMost(1f)    }}/** * Speaker pre-check — bridges wake-word detection to speaker recognition. * * **Previously**: hardcoded `return true` — anyone could unlock NOUS by voice. * **Now**: delegates to [SpeakerRecognitionEngine] (injected via * [SpeakerPreCheckBridge] at app startup). If no engine is registered (e.g., * during early boot before Hilt graph is ready), returns `false` — safe default * that blocks wake-word activation until the real engine is available. * * Audit Task ID: audit-m5-voice P0 — security hole fix. * * @see SpeakerPreCheckBridge * @see com.roshan.persona.voice.speaker.SpeakerRecognitionEngine */object SpeakerPreCheck {    /** Threshold for cosine similarity to consider a match (0.65 = strict). */    private const val MATCH_THRESHOLD = 0.65f    /** Max audio duration to consider (3 seconds at 16 kHz = 48k samples). */    private const val MAX_AUDIO_SAMPLES = 48_000    /**     * Returns true if the audio matches the enrolled owner voice print.     *     * Behavior:     *  - If no SpeakerRecognitionEngine is registered (early boot), returns false.     *  - If no owner voice print is enrolled, returns true (graceful degradation —     *    speaker pre-check is opt-in, so no enrollment = no check).     *  - If owner enrolled, computes MFCC embedding + cosine similarity against     *    the owner's stored voice print. Returns true iff similarity ≥ threshold.     */    fun matchesOwner(audio: ShortArray): Boolean {        val engine = SpeakerPreCheckBridge.speakerRecognitionEngine ?: return false        val ownerPrints = SpeakerPreCheckBridge.ownerVoicePrints        if (ownerPrints.isEmpty()) return true  // No enrollment = no check (opt-in)        return try {            // Truncate audio to max length for MFCC stability.            val trimmed = if (audio.size > MAX_AUDIO_SAMPLES) {                audio.copyOf(MAX_AUDIO_SAMPLES)            } else {                audio            }            // Use kotlinx.coroutines runBlocking since matchesOwner is non-suspend            // but SpeakerRecognitionEngine.identify is suspend.            val result = kotlinx.coroutines.runBlocking {                engine.identify(trimmed)            }            // SpeakerMatchResult is a data class — use isMatched + matchedSpeakerId.            if (!result.isMatched) return false            val matchedId = result.matchedSpeakerId ?: return false            val isOwner = ownerPrints.any { it.speakerId == matchedId }            isOwner && result.similarity >= MATCH_THRESHOLD        } catch (t: Throwable) {            Timber.tag("SpeakerPreCheck").e(t, "matchesOwner failed")            false  // Fail closed.        }    }}/** * Static bridge for [SpeakerPreCheck] to access the Hilt-provided * [com.roshan.persona.voice.speaker.SpeakerRecognitionEngine] + owner voice prints. * * Set by [com.roshan.persona.voice.di.VoiceModule] at app startup. Same pattern * as `SosLocationWorkerBridge` in Module 11. */object SpeakerPreCheckBridge {    @Volatile    var speakerRecognitionEngine: com.roshan.persona.voice.speaker.SpeakerRecognitionEngine? = null    @Volatile    var ownerVoicePrints: List<com.roshan.persona.voice.speaker.VoicePrint> = emptyList()}// ──────────────────────────────────────────────────────────────────────────// WakeWordTfliteModel — thin wrapper around TFLite Interpreter.// Real impl lives in :native:openwakeword. Stubbed here so :feature:voice// compiles without the native dependency during early development.// ──────────────────────────────────────────────────────────────────────────/** * OpenWakeWord TFLite model wrapper (4 MB). * * Real implementation will use: * ```kotlin * val options = Interpreter.Options().setDelegate(NnApiDelegate()) * val interpreter = Interpreter(modelBuffer, options) * ``` * * Until :native:openwakeword ships, [infer] returns a permissive score so * software detection always fires (acceptable during early development — * false positives are cheap). */class WakeWordTfliteModel private constructor(    private val modelFile: File,) {    /** Run wake-word inference on one audio chunk. Returns 0.0–1.0 confidence. */    fun infer(chunk: ShortArray): Float {        require(chunk.size == AudioCapturePipeline.CHUNK_SAMPLES) {            "Wake-word model expects ${AudioCapturePipeline.CHUNK_SAMPLES} samples, got ${chunk.size}"        }        // Real impl: reshape chunk → input tensor → interpreter.run() → read output.        // Stub: permissive score based on energy so dev builds always trigger.        var sumSq = 0L        for (s in chunk) sumSq += s.toInt().toLong() * s.toInt().toLong()        val rms = kotlin.math.sqrt(sumSq.toDouble() / chunk.size).toFloat()        return (rms / 6000f).coerceIn(0f, 1f)    }    /** Release the TFLite interpreter. */    fun close() {        // Real impl: interpreter.close()    }    companion object {        /** Load the model from [file]. Throws on parse error. */        fun load(file: File): WakeWordTfliteModel {            require(file.exists() && file.isFile) { "Model file missing: ${file.path}" }            // Real impl: MappedByteBuffer.fromFile(file) + Interpreter.Options            return WakeWordTfliteModel(file)        }    }}